def compare_one(a, b):
    def to_float(x):
        if isinstance(x, str):
            x = x.strip()
            if ',' in x and '.' in x:
                if x.rfind(',') > x.rfind('.'):
                    x = x.replace('.', '').replace(',', '.')
                else:
                    x = x.replace(',', '')
            elif ',' in x:
                if x.count(',') == 1 and len(x.split(',')[1]) == 1:
                    x = x.replace(',', '.')
                else:
                    x = x.replace(',', '')
            return float(x)
        return float(x)

    fa, fb = to_float(a), to_float(b)
    if fa == fb:
        return None
    return a if fa > fb else b
